function issueEvent(options: {
  action: string;
  labels?: Array<{ id: string; name: string }>;
  previousLabelIds?: string[];
  includeUpdatedFrom?: boolean;
}) {
  const payload = {
    action: options.action,
    type: "Issue",
    organizationId: "org",
    data: {
      id: "issue",
      teamId: "team",
      labelIds: (options.labels ?? []).map(({ id }) => id),
      labels: options.labels ?? [],
