      /JSON object/,
    );
    expect(() => parseRepository("acme/product/other")).toThrow(/Invalid GitHub/);
    expect(() => parseRepository("https://github.com/acme/product")).toThrow(
      /Invalid GitHub/,
    );
  });
});

