import * as v from "valibot";
import { issueTemplateOutline } from "../shared/issue-standard.ts";
import { repositoryForTeam } from "../shared/repository-config.ts";
import { linearIssueTools } from "../tools/linear-issue.ts";
import { repositoryReadTools } from "../tools/repository-read.ts";

const initialDataSchema = v.object({
  issueId: v.string(),
});

export function IssueStrengthener() {
  useModel("openrouter/~google/gemini-flash-latest");

  const initialData = useInitialData<v.InferOutput<typeof initialDataSchema>>();
  if (!initialData) {
    throw new Error("IssueStrengthener must be created by the Linear channel.");
  }

  const delivery = useDelivery();
  const attributes = delivery.kind === "signal" ? delivery.attributes : undefined;
  const teamId = stringAttribute(attributes?.teamId);
  const deliveryId = stringAttribute(attributes?.deliveryId);
  if (!teamId || !deliveryId) {
    throw new Error("The Linear trigger is missing its trusted team or delivery ID.");
  }

  const [conflictCount, setConflictCount] = usePersistentState(
    `linear-conflicts:${deliveryId}`,
    0,
  );
  const linearTools = linearIssueTools(
    { issueId: initialData.issueId, teamId, deliveryId },
    {
      conflictCount,
      recordConflict: () => setConflictCount(conflictCount + 1),
    },
  );
  useTool(linearTools.getIssue);
  useTool(linearTools.publish);
  useTool(linearTools.reportRepositoryUnavailable);

  const repository = repositoryForTeam(teamId);
  if (repository) {
    for (const tool of repositoryReadTools(repository)) useTool(tool);
  }

  useAgentFinish(({ response, append }) => {
    const succeeded = (tool: string) =>
      response.toolCalls.filter((call) => call.tool === tool && !call.isError).length;
    const unavailable = succeeded("report_repository_unavailable") > 0;
    const publishCalls = succeeded("publish_strengthened_issue");
    const publicationFinished = publishCalls >= conflictCount + 1;
    if (unavailable || publicationFinished) return;

    const terminalAttempts = response.toolCalls.filter((call) =>
      ["publish_strengthened_issue", "report_repository_unavailable"].includes(call.tool),
    ).length;
    if (terminalAttempts >= 3) return;

    append({
      kind: "signal",
      type: "linear.issue_strengthening.required",
      body: repository
        ? "The issue has not reached a terminal outcome. Publish it, regenerate after the first conflict, or report the repository unavailable if GitHub access failed."
        : "No repository is mapped for this team. Call report_repository_unavailable and leave the issue unchanged.",
    });
  });

  const repositoryInstructions = repository
    ? `The trusted repository is ${repository.owner}/${repository.repo}. Use the repository tools to inspect its default branch. If any repository tool fails, do not rewrite the issue; call report_repository_unavailable.`
    : "No repository is mapped for this Linear team. Immediately call report_repository_unavailable. Do not rewrite the title or description.";

  return `You strengthen implementation tickets using verified evidence from their mapped codebase.

${repositoryInstructions}

